class CacheModule(context: ReactApplicationContext, private val cache: DiskCache)
    : NativeCacheSpec(context) {
    private val scope = CoroutineScope(SupervisorJob() + Dispatchers.Main.immediate)
    override fun read(key: String, promise: Promise) {
        scope.launch {
            try {
                promise.resolve(withContext(Dispatchers.IO) { cache.read(key) })
            } catch (cancelled: CancellationException) {
                promise.reject("E_CANCELLED", "Module work cancelled")
                throw cancelled
            } catch (error: IOException) {
                promise.reject("E_READ", "Cache unavailable")
            }
        }
    }
    override fun invalidate() { scope.cancel(); super.invalidate() }
}

